Uint16List? _gbkTableCache;

Uint16List get gbkTable {
  final cached = _gbkTableCache;
  if (cached != null) return cached;
  final bytes = base64Decode(_gbkTableBase64);
  final view = Uint16List.view(bytes.buffer, bytes.offsetInBytes, bytes.length ~/ 2);
  _gbkTableCache = view;
  return view;
}

/// 查表解码单个 GBK 双字节字符,无效返回 null。
int? gbkLookup(int lead, int trail) {
  if (lead < gbkLeadMin || lead > 0xFE) return null;
  if (trail < gbkTrailMin || trail > 0xFE) return null;
  final idx = (lead - gbkLeadMin) * gbkTrailCount + (trail - gbkTrailMin);
  final code = gbkTable[idx];
  return code == 0 ? null : code;
}
